 ],
 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "medium",
   "message": "The lease has no limitation of liability clause, so Northwind's exposure to the Landlord is uncapped.",
   "quote": "Neither Party shall be liable for any delay caused by events beyond its reasonable control."
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "The lease has no early termination right, so Northwind is committed to rent for the full 36-month term even if its needs change.",
   "quote": "This Agreement shall remain in force for a period of thirty-six (36) months commencing on the Effective Date."
  },
  {
   "id": "renewal_terms_unspecified",
   "severity": "medium",
   "message": "The 5-year renewal option has no notice deadline and no stated rent for the renewal period, which creates uncertainty and the risk of a dispute or of losing the option.",
   "quote": "Tenant shall hold one (1) option to renew the lease for an additional period of five (5) years, exercisable by written notice to Landlord."
  },
  {
   "id": "no_payment_terms_or_late_rules",
   "severity": "low",
   "message": "The lease says rent is paid in monthly installments but gives no due date, grace period or late-fee rules.",
   "quote": "The annual base rent shall be payable in equal monthly installments."
  },
  {
   "id": "security_deposit_terms_missing",
   "severity": "low",
   "message": "The security deposit is two months' rent (about USD 24,000), but the lease says nothing about when it is returned or what it can be applied to.",
   "quote": "Tenant shall deliver to Landlord a security deposit in an amount equal to two (2) months' base rent."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a 36-month commercial office lease between Northwind Labs, Inc. (Tenant) and Lakeside Commons REIT, Inc. (Landlord) for 400 Harbor Street, Suite 12, at USD 144,000 per year, governed by Ontario law. It gives Northwind a 5-year renewal option but has no liability cap, no early termination right and little detail on renewal or deposit terms."
